// Lazy per-faction datasheet loader. Each src/data/datasheets/<slug>.js (generated by
// scripts/import-wahapedia-datasheets.mjs) is code-split into its own chunk via
// import.meta.glob and only fetched when FactionView shows that faction — the datasheet
// data must never be imported statically (it would bloat the shared FactionView chunk).
const modules = import.meta.glob(['./*.js', '!./index.js'])

export function loadDatasheets(slug) {
  const loader = modules[`./${slug}.js`]
  return loader ? loader().then((m) => m.default) : Promise.resolve(null)
}
